oldNestedNativeReconciliation:
if stage_receipt is not None and m['mode'] == 'original21':
    baseline_path = stage_receipt / 'tmp-baseline.json'
    if baseline_path.exists():
        baseline = json.loads(baseline_path.read_text())
        require(isinstance(baseline, list) and all(isinstance(x, str) for x in baseline), 'Bad fresh receipt baseline')
        for directory in pathlib.Path('/tmp').glob('starship-official-flight.*'):
            if str(directory) in baseline: continue
            require(directory.resolve() == directory and directory.is_dir(), 'Foreign fresh flight directory')
            for name in ('native-build.process.json', 'official-tests.process.json'):
                actual = directory / 'native.receipts' / name
                if not actual.exists(): continue
                try:
                    receipt = json.loads(actual.read_text())
                    cleanup = receipt.get('cleanup')
                    require(isinstance(cleanup, dict), 'Nested cleanup missing')
                    anchor = known.get((cleanup['pid'], cleanup['start']))
                    require(anchor is not None and anchor['group'] == cleanup['group'] and anchor['session'] == cleanup['session'], 'Fresh receipt leader not independently observed')
                    for row in cleanup.get('tracked', []):
                        for key in ('pid', 'start', 'group', 'session'): require(key in row, 'Malformed nested product identity')
                        admit(row)
                    save('nested-' + directory.name + '-' + name, {'path': str(actual), 'sha256': digest(actual), 'cleanup': cleanup})
                except BaseException as error:
                    failures.append('Nested product receipt reconciliation: ' + str(error))

finalProviderHashCheck:
for path, captured in provider_files.items():
    try: require(digest(path) == captured['sha256'], 'Final provider artifact drift: ' + path)
    except BaseException as error: failures.append(str(error))
